<script setup lang="ts">
import { computed, ref } from 'vue'
import { app, joinCode, joinLocal, answerScroll } from '../session'
import { mine, choose, chosen } from '../heroes'
import { sheet } from '../rules/hero'
import Bar from './Bar.vue'
import Portrait from './Portrait.vue'
import QR from './QR.vue'
import Scan from './Scan.vue'
const inv = app.inviteHash; const code = ref(inv?.k === 'r' ? inv.v : ''), tab = ref<'code' | 'scroll'>(inv?.k === 'j' ? 'scroll' : 'code'), their = ref(inv?.k === 'j' ? inv.v : ''), reply = ref(''), scan = ref(false), busy = ref(false), copied = ref(false); const h = computed(() => chosen()); const ok = computed(() => !!h.value && !h.value.dead)
const go = () => { if (inv?.k === 'l' && tab.value === 'code' && !code.value) joinLocal(inv.v); else joinCode(code.value) }; const answer = async () => { busy.value = true; const a = await answerScroll(their.value); busy.value = false; if (a) reply.value = a }; const copy = async () => { await navigator.clipboard.writeText(reply.value); copied.value = true; setTimeout(() => copied.value = false, 1600) }; const got = (t: string) => { scan.value = false; const m = t.match(/#j=(.+)$/); their.value = m ? decodeURIComponent(m[1]) : t; answer() }; const make = () => { app.modalArg = 'join'; app.screen = 'heroes' }; const back = () => { app.inviteHash = null; app.screen = 'title' }
</script>
<template><main class="jn paper"><Bar title="Join a table" @back="back" /><div class="bd scroll"><div class="two"><section><h2>Who will you be?</h2><p v-if="!mine.list.length">You need a hero before you may sit down: make one here, or bring the sheet you already play.</p><div v-else class="hl scroll"><button v-for="x in mine.list" :key="x.id" :disabled="x.dead" :class="{ on: mine.chosen === x.id }" @click="choose(x.id)"><Portrait :hero="x" :size="64" /><span class="grow"><b class="cut">{{ x.name }}</b><small>{{ x.over?.race ?? sheet(x).race.name }} {{ x.over?.cls ?? sheet(x).cls.name.toLowerCase() + ' ' + x.level }}<template v-if="x.dead">, fallen</template></small></span></button></div><button class="btn wide" :class="{ primary: !mine.list.length, big: !mine.list.length }" @click="make">Make or bring a hero</button><label class="lab" for="pn" style="margin-top:20px">Your own name, so the others know who is playing</label><input id="pn" v-model="app.name" class="field" maxlength="24"></section>
  <section :class="{ off: !ok }"><h2>Which table?</h2><div class="tabs" style="margin-bottom:16px"><button class="tab" :class="{ on: tab === 'code' }" @click="tab = 'code'">Room code</button><button class="tab" :class="{ on: tab === 'scroll' }" @click="tab = 'scroll'">By hand</button></div><template v-if="tab === 'code'"><p v-if="inv?.k === 'l'">You were invited from another window on this device.</p><form v-else @submit.prevent="go"><input v-model="code" class="code" placeholder="raven-keep-42" aria-label="Room code" autocapitalize="off" autocomplete="off" spellcheck="false"></form><button class="btn primary big wide" style="margin-top:14px" :disabled="!ok" @click="go">Sit down</button></template>
  <template v-else><p>No internet, or a strict network? Paste or scan the Dungeon Master’s scroll, then hand your reply back.</p><template v-if="!reply"><textarea v-model="their" class="field" rows="4" placeholder="Paste the scroll" aria-label="Scroll" /><div class="row" style="margin-top:8px"><button class="btn grow" @click="scan = true">Scan</button><button class="btn primary grow" :disabled="!their || busy || !ok" @click="answer">{{ busy ? 'Writing…' : 'Write my reply' }}</button></div></template><template v-else><p>Show this to the Dungeon Master, or send the text.</p><QR :text="reply" /><button class="btn wide" @click="copy">{{ copied ? 'Copied' : 'Copy the reply' }}</button></template></template></section></div></div><Scan v-if="scan" @found="got" @close="scan = false" /></main></template>
<style scoped>.jn{position:fixed;inset:0;display:flex;flex-direction:column}.bd{flex:1;min-height:0}.two{display:grid;grid-template-columns:1fr 1fr;min-height:100%}section{padding:30px clamp(18px,4vw,70px) 50px;max-width:760px}section+section{border-left:2px solid var(--ink)}h2{font:800 38px/1 var(--serif);margin-bottom:16px}.hl{border:2px solid var(--ink);max-height:46vh;margin-bottom:10px}.hl button{display:flex;align-items:center;gap:14px;width:100%;border-bottom:1px solid var(--line2)}.hl button:last-child{border:0}.hl button:hover{background:var(--paper2)}.hl .on{background:var(--spot)!important;color:var(--on-spot)}.hl .on small{color:inherit}.hl button:disabled{opacity:.45}.hl b{display:block;font:700 22px/1.05 var(--serif)}.hl small{font-size:16px;color:var(--ink2)}.off{opacity:.4}.code{width:100%;font:800 40px/1.2 var(--serif);border:0;border-bottom:4px solid var(--ink);background:none;color:var(--ink);padding:4px 0;outline:none}.code:focus{border-color:var(--spot)}.code::placeholder{color:var(--paper3)}@media(max-width:760px){.two{grid-template-columns:1fr}section+section{border-left:0;border-top:2px solid var(--ink)}section{padding-top:20px;padding-bottom:24px}.hl{max-height:32vh}}</style>
